        "functions": [
          {
            "function": "minecraft:set_nbt",
            "tag": "{title:\"On Bitter Brews\",author:\"Selene\",pages:['{\"text\":\"Always mark the red bottles. A draught of Healing can mend a cut, but it will not mend a burnt tongue.\"}','{\"text\":\"Swiftness needs sugar. Water Breathing needs pufferfish. The mix curdles if heated too long. I tried it on a stray cat; it hissed and dove into the basin without fear.\"}']}"
          }
        ]
      },
      {
        "type": "minecraft:item",
        "weight": 3,
        "name": "minecraft:written_book",
        "functions": [
          {
            "function": "minecraft:set_nbt",
            "tag": "{title:\"Poison Notes\",author:\"Krell\",pages:['{\"text\":\"Fermented spider eye turns a clear potion sour. The first sip is sweet, the second is trouble.\"}','{\"text\":\"Weakness comes from a steady hand and a small dose. I tested on mice and a coop hen. The hen glared, but lived.\"}']}"
          }
        ]
      },
      {
        "type": "minecraft:item",
        "weight": 2,
        "name": "minecraft:written_book",
        "functions": [
          {
            "function": "minecraft:set_nbt",
            "tag": "{title:\"Quiet Sorceries\",author:\"R. Thatch\",pages:['{\"text\":\"Some pages whisper about binding shadows and bending will. I keep them locked and read them once, with a candle and a steady door.\"}','{\"text\":\"Invisibility takes the night and a golden carrot. Night Vision takes the glow of a carrot and a spider\\'s eye. If the recipe asks for a Wither Rose, close the book.\"}']}"
