      "name": "minecraft:written_book",
      "functions": [
        {
          "function": "minecraft:set_nbt",
          "tag": "{title:\"Bazaar Ledger: Day 18\",author:\"Rafiq\",pages:['{\"text\":\"Bought 12 pieces of leather, sold 9. Paid two emeralds in shade money to keep the awning up.\"}','{\"text\":\"Water price doubled at noon. A caravan from the south brought dates and cracked pottery. The pottery still sold.\"}']}"
        }
      ]
    },
    {
      "type": "minecraft:item",
      "weight": 3,
      "name": "minecraft:written_book",
      "functions": [
        {
          "function": "minecraft:set_nbt",
          "tag": "{title:\"Salt and Silk\",author:\"Minaq\",pages:['{\"text\":\"Traded six sacks of salt for one chest of silk. The buyer swore it was moon-white. It was off-white, but soft.\"}','{\"text\":\"Reminder: copper ingots carry better than coins in the dunes. Coins clink. Raiders listen.\"}']}"
        }
      ]
    },
    {
      "type": "minecraft:item",
      "weight": 3,
      "name": "minecraft:written_book",
      "functions": [
        {
          "function": "minecraft:set_nbt",
          "tag": "{title:\"Caravan Log: West Dunes\",author:\"Jalen\",pages:['{\"text\":\"Three wagons lost a wheel on day two. Replaced with acacia and a prayer.\"}','{\"text\":\"Scorpions at camp, but the camels held steady. Found a shrine of bleached stone and left a coin.\"}']}"
        }
      ]
    },
    {
      "type": "minecraft:item",
      "weight": 2,
      "name": "minecraft:written_book",
      "functions": [
        {
          "function": "minecraft:set_nbt",
          "tag": "{title:\"Stall Rules, Written Small\",author:\"Bazaar Clerk\",pages:['{\"text\":\"No sales during the bell. No shouting over the spice guild. Keep blades sheathed after dusk.\"}','{\"text\":\"If a trade is disputed, walk to the blue tent. Do not argue in the sand.\"}']}"
        }
      ]
    },
    {
      "type": "minecraft:item",
      "weight": 2,
      "name": "minecraft:written_book",
      "functions": [
        {
          "function": "minecraft:set_nbt",
          "tag": "{title:\"The Labyrinth\",author:\"Old Nura\",pages:['{\"text\":\"There is a maze out in the deep desert. Stone walls, no shade, a treasure at its heart if the stories are true.\"}','{\"text\":\"The sand keeps its own secrets. If you go, mark your way. If you return, bring water for the next fool.\"}']}"
        }
      ]
    },
    {
      "type": "minecraft:item",
      "weight": 2,
      "name": "minecraft:written_book",
      "functions": [
        {
          "function": "minecraft:set_nbt",
          "tag": "{title:\"Missing Crates\",author:\"Safa\",pages:['{\"text\":\"Two crates of glass beads vanished between the north gate and stall 14. Guards blame wind. Wind does not lock latches.\"}','{\"text\":\"If found, return for double pay. If not found, I will find you.\"}']}"
        }
      ]
    },
    {
      "type": "minecraft:item",
      "weight": 2,
      "name": "minecraft:written_book",
      "functions": [
        {
          "function": "minecraft:set_nbt",
          "tag": "{title:\"Map Without a Map\",author:\"Tamar\",pages:['{\"text\":\"Walk by the sun when it kisses the far dune. The stone finger points west. The dry well is your last shade.\"}','{\"text\":\"If the wind buries the markers, trust the stars and the taste of the air. It always turns iron before a storm.\"}']}"
        }
      ]
    }
  ]
}

